import math


def evaluate(expr: str) -> int:
    if not isinstance(expr, str):
        raise ValueError("Expression must be a string")

    PRECEDENCE = {
        "+": 1,
        "-": 1,
        "*": 2,
        "/": 2,
        "%": 2,
        "UMINUS": 3,
        "^": 4,
    }

    val_stack: list[int] = []
    op_stack: list[str] = []

    def apply_op(op: str) -> None:
        if op == "UMINUS":
            val_stack[-1] = -val_stack[-1]
            return
        b = val_stack.pop()
        a = val_stack[-1]
        if op == "+":
            val_stack[-1] = a + b
        elif op == "-":
            val_stack[-1] = a - b
        elif op == "*":
            val_stack[-1] = a * b
        elif op == "/":
            if b == 0:
                raise ValueError("Division by zero")
            q = abs(a) // abs(b)
            val_stack[-1] = -q if (a < 0) ^ (b < 0) else q
        elif op == "%":
            if b == 0:
                raise ValueError("Modulo by zero")
            r = abs(a) % abs(b)
            val_stack[-1] = -r if a < 0 else r
        elif op == "^":
            if b < 0:
                raise ValueError("Negative exponent")
            val_stack[-1] = a**b

    def push_binary_op(op: str) -> None:
        prec = PRECEDENCE[op]
        if op == "^":
            while (
                op_stack and op_stack[-1] != "(" and PRECEDENCE[op_stack[-1]] > prec
            ):
                apply_op(op_stack.pop())
        else:
            while (
                op_stack
                and op_stack[-1] != "("
                and PRECEDENCE[op_stack[-1]] >= prec
            ):
                apply_op(op_stack.pop())
        op_stack.append(op)

    expect_operand = True
    i = 0
    n = len(expr)

    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
            continue

        if "0" <= ch <= "9":
            if not expect_operand:
                raise ValueError("Unexpected number")
            j = i + 1
            while j < n and "0" <= expr[j] <= "9":
                j += 1
            val_stack.append(int(expr[i:j]))
            i = j
            expect_operand = False
        elif ch == "(":
            if not expect_operand:
                push_binary_op("*")
            op_stack.append("(")
            i += 1
            expect_operand = True
        elif ch == ")":
            if expect_operand:
                raise ValueError("Unexpected ')'")
            while op_stack and op_stack[-1] != "(":
                apply_op(op_stack.pop())
            if not op_stack:
                raise ValueError("Mismatched ')'")
            op_stack.pop()
            i += 1
            expect_operand = False
        elif ch == "!":
            if expect_operand:
                raise ValueError("Unexpected '!'")
            if val_stack[-1] < 0:
                raise ValueError("Factorial of negative number")
            val_stack[-1] = math.factorial(val_stack[-1])
            i += 1
        elif ch in "+-*/%^":
            if expect_operand:
                if ch == "-":
                    op_stack.append("UMINUS")
                else:
                    raise ValueError(f"Unexpected operator '{ch}'")
            else:
                push_binary_op(ch)
                expect_operand = True
            i += 1
        else:
            raise ValueError(f"Invalid character '{ch}'")

    if expect_operand:
        raise ValueError("Unexpected end of expression")

    while op_stack:
        op = op_stack.pop()
        if op == "(":
            raise ValueError("Mismatched '('")
        apply_op(op)

    if len(val_stack) != 1:
        raise ValueError("Malformed expression")

    return val_stack[0]
